"use client";

/**
 * MultiImageUpload.tsx
 * Upload, preview, delete, reorder up to 5 images per post.
 * - Drag & drop reorder via HTML5 DnD
 * - Counter: 0/5 → 5/5
 * - Primary image = first in array
 * - Blocks upload when at max
 */

import { useRef, useState, useCallback } from "react";
import { MAX_IMAGES_PER_POST } from "@/lib/richTextUtils";
import { uploadContentMedia } from "@/services/contentService";
import { validateMediaFile } from "@/lib/mediaUpload";

interface MultiImageUploadProps {
  images: string[];
  onChange: (urls: string[]) => void;
  /** Optional: override upload function (for testing) */
  onUpload?: (file: File) => Promise<string>;
  className?: string;
}

export default function MultiImageUpload({
  images,
  onChange,
  onUpload,
  className = "",
}: MultiImageUploadProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
  const dragSrcIndex = useRef<number | null>(null);

  const atMax = images.length >= MAX_IMAGES_PER_POST;

  // ---------------------------------------------------------------------------
  // Upload
  // ---------------------------------------------------------------------------

  const handleFileChange = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = Array.from(e.target.files ?? []);
      e.target.value = "";
      if (files.length === 0) return;

      const remaining = MAX_IMAGES_PER_POST - images.length;
      const toUpload = files.slice(0, remaining);

      if (files.length > remaining) {
        setUploadError(`Maximum ${MAX_IMAGES_PER_POST} images allowed per post.`);
      } else {
        setUploadError(null);
      }

      setUploading(true);
      const newUrls: string[] = [];
      for (const file of toUpload) {
        const validationError = validateMediaFile(file, "image");
        if (validationError) {
          setUploadError(validationError);
          continue;
        }
        try {
          const uploadFn = onUpload ?? ((f: File) => uploadContentMedia(f, "image"));
          const url = await uploadFn(file);
          newUrls.push(url);
        } catch (err: unknown) {
          const msg = err instanceof Error ? err.message : "Upload failed";
          setUploadError(msg);
        }
      }
      setUploading(false);

      if (newUrls.length > 0) {
        onChange([...images, ...newUrls]);
      }
    },
    [images, onChange, onUpload]
  );

  const handleDrop = useCallback(
    async (e: React.DragEvent) => {
      e.preventDefault();
      setDragOverIndex(null);
      if (atMax) return;

      const files = Array.from(e.dataTransfer.files).filter((f) =>
        f.type.startsWith("image/")
      );
      if (files.length === 0) return;

      const remaining = MAX_IMAGES_PER_POST - images.length;
      const toUpload = files.slice(0, remaining);

      setUploading(true);
      const newUrls: string[] = [];
      for (const file of toUpload) {
        try {
          const uploadFn = onUpload ?? ((f: File) => uploadContentMedia(f, "image"));
          const url = await uploadFn(file);
          newUrls.push(url);
        } catch (err: unknown) {
          setUploadError(err instanceof Error ? err.message : "Upload failed");
        }
      }
      setUploading(false);
      if (newUrls.length > 0) onChange([...images, ...newUrls]);
    },
    [images, onChange, onUpload, atMax]
  );

  // ---------------------------------------------------------------------------
  // Delete
  // ---------------------------------------------------------------------------

  const removeImage = useCallback(
    (index: number) => {
      const updated = images.filter((_, i) => i !== index);
      onChange(updated);
      setUploadError(null);
    },
    [images, onChange]
  );

  // ---------------------------------------------------------------------------
  // Reorder (drag & drop)
  // ---------------------------------------------------------------------------

  const handleDragStart = (index: number) => {
    dragSrcIndex.current = index;
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
    // Only handle drag-over for reordering (not file drop) when dragging an existing image
    if (dragSrcIndex.current !== null) {
      e.preventDefault();
      setDragOverIndex(index);
    }
  };

  const handleDragEnd = () => {
    dragSrcIndex.current = null;
    setDragOverIndex(null);
  };

  const handleDropOnImage = (e: React.DragEvent, targetIndex: number) => {
    e.preventDefault();
    const srcIndex = dragSrcIndex.current;
    dragSrcIndex.current = null;
    setDragOverIndex(null);

    if (srcIndex === null || srcIndex === targetIndex) return;

    const updated = [...images];
    const [moved] = updated.splice(srcIndex, 1);
    updated.splice(targetIndex, 0, moved);
    onChange(updated);
  };

  // ---------------------------------------------------------------------------
  // Replace single image
  // ---------------------------------------------------------------------------

  const replaceImageInputRef = useRef<HTMLInputElement>(null);
  const replaceIndexRef = useRef<number | null>(null);

  const handleReplace = (index: number) => {
    replaceIndexRef.current = index;
    replaceImageInputRef.current?.click();
  };

  const handleReplaceFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file || replaceIndexRef.current === null) return;

    const validationError = validateMediaFile(file, "image");
    if (validationError) { setUploadError(validationError); return; }

    setUploading(true);
    try {
      const uploadFn = onUpload ?? ((f: File) => uploadContentMedia(f, "image"));
      const url = await uploadFn(file);
      const updated = [...images];
      updated[replaceIndexRef.current] = url;
      onChange(updated);
      setUploadError(null);
    } catch (err: unknown) {
      setUploadError(err instanceof Error ? err.message : "Upload failed");
    } finally {
      setUploading(false);
      replaceIndexRef.current = null;
    }
  };

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <div className={`space-y-3 ${className}`}>
      {/* Hidden file inputs */}
      <input
        ref={fileInputRef}
        type="file"
        accept="image/jpeg,image/png,image/webp,image/gif"
        multiple
        className="hidden"
        onChange={handleFileChange}
      />
      <input
        ref={replaceImageInputRef}
        type="file"
        accept="image/jpeg,image/png,image/webp,image/gif"
        className="hidden"
        onChange={handleReplaceFileChange}
      />

      {/* Label + counter */}
      <div className="flex items-center justify-between">
        <label className="text-label-sm text-on-surface-variant font-semibold">
          Images
        </label>
        <span
          className={`text-label-xs font-semibold px-2 py-0.5 rounded-full ${
            atMax
              ? "bg-orange-100 text-orange-600"
              : images.length > 0
              ? "bg-primary/10 text-primary"
              : "bg-surface-container text-outline"
          }`}
        >
          {images.length} / {MAX_IMAGES_PER_POST}
        </span>
      </div>

      {/* Image Grid */}
      {images.length > 0 && (
        <div
          className="grid grid-cols-3 gap-2"
          onDragOver={(e) => {
            // Allow file drops onto the grid
            if (dragSrcIndex.current === null) e.preventDefault();
          }}
          onDrop={(e) => {
            if (dragSrcIndex.current === null) handleDrop(e);
          }}
        >
          {images.map((url, index) => (
            <div
              key={`${url}-${index}`}
              draggable
              onDragStart={() => handleDragStart(index)}
              onDragOver={(e) => handleDragOver(e, index)}
              onDragEnd={handleDragEnd}
              onDrop={(e) => handleDropOnImage(e, index)}
              className={`relative rounded-xl overflow-hidden border-2 transition-all cursor-grab active:cursor-grabbing ${
                dragOverIndex === index
                  ? "border-primary scale-105 shadow-lg"
                  : index === 0
                  ? "border-primary/40"
                  : "border-outline-variant/20"
              }`}
            >
              <div className="aspect-square bg-surface-container">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  src={url}
                  alt={`Image ${index + 1}`}
                  className="w-full h-full object-cover"
                  draggable={false}
                />
              </div>

              {/* Primary badge */}
              {index === 0 && (
                <div className="absolute top-1 left-1 px-1.5 py-0.5 rounded-md bg-primary text-on-primary text-label-2xs font-bold">
                  Cover
                </div>
              )}

              {/* Order badge */}
              <div className="absolute top-1 right-1 w-5 h-5 rounded-full bg-black/50 text-white text-[10px] font-bold flex items-center justify-center">
                {index + 1}
              </div>

              {/* Action buttons */}
              <div className="absolute bottom-1 right-1 flex gap-1">
                <button
                  type="button"
                  onClick={(e) => { e.stopPropagation(); handleReplace(index); }}
                  className="w-6 h-6 rounded-md bg-black/60 text-white flex items-center justify-center hover:bg-black/80 transition-all"
                  title="Replace image"
                >
                  <span className="material-symbols-outlined text-[12px]">refresh</span>
                </button>
                <button
                  type="button"
                  onClick={(e) => { e.stopPropagation(); removeImage(index); }}
                  className="w-6 h-6 rounded-md bg-black/60 text-white flex items-center justify-center hover:bg-red-500/80 transition-all"
                  title="Remove image"
                >
                  <span className="material-symbols-outlined text-[12px]">close</span>
                </button>
              </div>

              {/* Drag handle hint */}
              <div className="absolute bottom-1 left-1 w-6 h-6 rounded-md bg-black/40 text-white/60 flex items-center justify-center">
                <span className="material-symbols-outlined text-[12px]">drag_indicator</span>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Add Image Button / Drop Zone */}
      {!atMax && (
        <div
          onDragOver={(e) => { e.preventDefault(); }}
          onDrop={handleDrop}
          onClick={() => !uploading && fileInputRef.current?.click()}
          className={`flex items-center gap-3 px-4 py-3 rounded-xl border-2 border-dashed cursor-pointer transition-all
            ${uploading
              ? "border-primary/30 bg-primary/5 cursor-wait"
              : "border-outline-variant/30 hover:border-primary/40 hover:bg-surface-container/50"
            }`}
        >
          <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
            {uploading ? (
              <span className="w-4 h-4 border-2 border-primary/30 border-t-primary rounded-full animate-spin" />
            ) : (
              <span className="material-symbols-outlined text-primary text-[18px]">add_photo_alternate</span>
            )}
          </div>
          <div>
            <p className="text-label-sm font-semibold text-on-surface">
              {uploading ? "Uploading..." : "Add Image"}
            </p>
            <p className="text-label-xs text-outline">
              {atMax
                ? `Maximum ${MAX_IMAGES_PER_POST} images reached`
                : `PNG, JPG, WebP, GIF · up to 50MB · ${images.length}/${MAX_IMAGES_PER_POST}`}
            </p>
          </div>
        </div>
      )}

      {/* At max message */}
      {atMax && (
        <div className="flex items-center gap-2 px-3 py-2 rounded-xl bg-orange-50 border border-orange-100">
          <span className="material-symbols-outlined text-orange-500 text-[16px]">warning</span>
          <p className="text-label-xs text-orange-600 font-medium">
            Maximum {MAX_IMAGES_PER_POST} images allowed per post. Remove an image to add another.
          </p>
        </div>
      )}

      {/* Upload error */}
      {uploadError && (
        <div className="flex items-center gap-2 px-3 py-2 rounded-xl bg-red-50 border border-red-100">
          <span className="material-symbols-outlined text-red-500 text-[16px]">error</span>
          <p className="text-label-xs text-red-600">{uploadError}</p>
        </div>
      )}

      {images.length > 1 && (
        <p className="text-label-xs text-outline">
          <span className="material-symbols-outlined text-[12px] align-middle mr-0.5">drag_indicator</span>
          Drag images to reorder. First image is used as cover.
        </p>
      )}
    </div>
  );
}

"use client";

/**
 * RichTextEditor.tsx
 * A rich text editor built on Tiptap with:
 * - Bold, Italic, Underline, Strikethrough
 * - Uppercase toggle
 * - Bullet list, Numbered list
 * - Emoji picker (inline)
 * - Paragraph / line break
 * - Markdown output for storage
 * - Backward compatible with legacy plaintext input
 */

import { useEditor, EditorContent } from "@tiptap/react";
import StarterKit from "@tiptap/starter-kit";
import UnderlineExtension from "@tiptap/extension-underline";
import Placeholder from "@tiptap/extension-placeholder";
import { useEffect, useState, useCallback, useRef } from "react";
import { marked } from "marked";

// Configure marked: no HTML sanitization here, we handle security at the render layer
// gfm = true enables ~~strikethrough~~, breaks = false preserves paragraph semantics
marked.setOptions({ gfm: true, breaks: false });

// ---------------------------------------------------------------------------
// Serialization helpers (Tiptap JSON → Markdown)
// ---------------------------------------------------------------------------

interface TiptapTextNode {
  type: "text";
  text: string;
  marks?: Array<{ type: string }>;
}

interface TiptapNode {
  type: string;
  content?: TiptapNode[];
  attrs?: Record<string, unknown>;
  text?: string;
  marks?: Array<{ type: string }>;
}

function serializeNode(node: TiptapNode): string {
  if (node.type === "text") {
    const textNode = node as TiptapTextNode;
    let text = textNode.text ?? "";
    const markTypes = (textNode.marks ?? []).map((m) => m.type);
    if (markTypes.includes("strike")) text = `~~${text}~~`;
    if (markTypes.includes("underline")) text = `<u>${text}</u>`;
    if (markTypes.includes("italic")) text = `*${text}*`;
    if (markTypes.includes("bold")) text = `**${text}**`;
    return text;
  }

  const children = (node.content ?? []).map(serializeNode).join("");

  switch (node.type) {
    case "paragraph":
      return children ? `${children}\n\n` : "\n";
    case "bulletList":
      return `${children}`;
    case "orderedList":
      return `${children}`;
    case "listItem":
      return `- ${children.trimEnd()}\n`;
    case "hardBreak":
      return "\n";
    case "heading": {
      const level = (node.attrs?.level as number) ?? 1;
      return `${"#".repeat(level)} ${children}\n\n`;
    }
    case "blockquote":
      return `> ${children}\n`;
    case "horizontalRule":
      return `---\n`;
    case "doc":
    default:
      return children;
  }
}

/** Convert Tiptap JSON doc to Markdown string */
function tiptapToMarkdown(doc: TiptapNode): string {
  const raw = serializeNode(doc);
  // Clean excessive newlines but keep paragraph breaks
  return raw.replace(/\n{3,}/g, "\n\n").trimEnd();
}

// ---------------------------------------------------------------------------
// Parsing helpers (Markdown → Tiptap HTML)
// ---------------------------------------------------------------------------

/**
 * Convert Markdown string to Tiptap-compatible HTML.
 *
 * Uses `marked` (AST-based parser) which correctly handles:
 *  - nested marks: **_Bold Italic_**, ~~**Bold Strike**~~
 *  - bullet/numbered lists with inline formatting
 *  - paragraphs and line breaks
 *  - emoji and unicode pass-through
 *
 * Underline is stored as raw `<u>` tag (Markdown has no underline syntax).
 * marked passes <u> through as inline HTML, so it round-trips correctly.
 *
 * Security: DOMPurify sanitization is applied at render time inside Tiptap.
 * This function intentionally leaves safe tags like <strong>, <em>, <u>, <s>,
 * <ul>, <ol>, <li>, <p> intact for Tiptap to parse.
 */
function markdownToHtml(markdown: string): string {
  if (!markdown) return "<p></p>";

  // marked does not know <u> (underline), but it passes inline HTML through
  // when pedantic=false (the default). So <u>text</u> survives as-is.
  const html = marked.parse(markdown, { async: false }) as string;

  // Tiptap needs at least one block element; if output is empty return a paragraph
  return html.trim() || "<p></p>";
}

// ---------------------------------------------------------------------------
// Quick emoji list
// ---------------------------------------------------------------------------

const QUICK_EMOJIS = [
  "🔥", "✨", "🎁", "🚀", "❤️", "💰", "👉", "🎯",
  "⭐", "💥", "🎉", "👑", "💎", "🏆", "✅", "📢",
  "🛍️", "💳", "🏷️", "📱", "💫", "🌟", "🔑", "🎊",
];

// ---------------------------------------------------------------------------
// Toolbar Button
// ---------------------------------------------------------------------------

function ToolbarBtn({
  onClick,
  active,
  disabled,
  title,
  children,
}: {
  onClick: () => void;
  active?: boolean;
  disabled?: boolean;
  title: string;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      title={title}
      className={`w-8 h-8 flex items-center justify-center rounded-lg text-[13px] font-semibold transition-all select-none
        ${active
          ? "bg-primary text-on-primary shadow-sm"
          : "text-on-surface-variant hover:bg-surface-container-high hover:text-on-surface"
        }
        ${disabled ? "opacity-40 cursor-not-allowed" : "cursor-pointer"}
      `}
    >
      {children}
    </button>
  );
}

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

interface RichTextEditorProps {
  value: string;
  onChange: (markdown: string) => void;
  placeholder?: string;
  minHeight?: number;
  className?: string;
}

export default function RichTextEditor({
  value,
  onChange,
  placeholder = "Write your content here...",
  minHeight = 200,
  className = "",
}: RichTextEditorProps) {
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const emojiPickerRef = useRef<HTMLDivElement>(null);
  const isInitialized = useRef(false);
  const externalValueRef = useRef(value);

  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        // Headings not needed for social posts
        heading: false,
        // Keep code block off
        code: false,
        codeBlock: false,
      }),
      UnderlineExtension,
      Placeholder.configure({
        placeholder,
        emptyNodeClass:
          "before:content-[attr(data-placeholder)] before:text-outline/40 before:float-left before:h-0 before:pointer-events-none before:text-body-sm",
      }),
    ],
    content: markdownToHtml(value),
    editorProps: {
      attributes: {
        class: `outline-none text-body-sm text-on-surface leading-relaxed [&>*+*]:mt-3 [&>ul]:pl-5 [&>ul>li]:list-disc [&>ol]:pl-5 [&>ol>li]:list-decimal`,
        style: `min-height: ${minHeight}px; padding: 12px;`,
      },
    },
    onUpdate: ({ editor: ed }) => {
      const json = ed.getJSON() as TiptapNode;
      const markdown = tiptapToMarkdown(json);
      externalValueRef.current = markdown;
      onChange(markdown);
    },
    immediatelyRender: false,
  });

  // Sync external value changes (e.g., AI fills in content)
  useEffect(() => {
    if (!editor) return;
    if (!isInitialized.current) {
      isInitialized.current = true;
      return;
    }
    // Only update if value differs from what we last emitted
    if (value !== externalValueRef.current) {
      const html = markdownToHtml(value);
      // Tiptap 3.x: setContent second arg is SetContentOptions, not boolean
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      editor.commands.setContent(html, { emitUpdate: false } as any);
      externalValueRef.current = value;
    }
  }, [editor, value]);

  // Close emoji picker on outside click
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (emojiPickerRef.current && !emojiPickerRef.current.contains(e.target as Node)) {
        setShowEmojiPicker(false);
      }
    };
    if (showEmojiPicker) document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [showEmojiPicker]);

  const insertEmoji = useCallback(
    (emoji: string) => {
      editor?.commands.insertContent(emoji);
      setShowEmojiPicker(false);
    },
    [editor]
  );

  // Uppercase the ENTIRE selection, preserving all existing marks (bold, italic, etc.)
  // This is a one-time text transformation. Use Ctrl+Z to undo.
  const handleUppercase = useCallback(() => {
    if (!editor) return;
    const { from, to, empty } = editor.state.selection;
    if (empty) return;

    // Use Tiptap's transaction to uppercase each text node individually,
    // which preserves all marks (bold, italic, underline, strike) on each node.
    const { state, dispatch } = editor.view;
    const { tr } = state;
    let modified = false;

    state.doc.nodesBetween(from, to, (node, pos) => {
      if (node.isText && node.text) {
        const nodeFrom = Math.max(pos, from);
        const nodeTo = Math.min(pos + node.nodeSize, to);
        if (nodeFrom < nodeTo) {
          const original = node.text.slice(nodeFrom - pos, nodeTo - pos);
          const upper = original.toUpperCase();
          if (upper !== original) {
            tr.insertText(upper, nodeFrom, nodeTo);
            modified = true;
          }
        }
      }
    });

    if (modified) {
      dispatch(tr);
      editor.commands.focus();
    }
  }, [editor]);

  if (!editor) return null;

  return (
    <div className={`relative bg-surface-container rounded-xl border border-outline-variant/20 focus-within:border-primary/40 focus-within:ring-2 focus-within:ring-primary/5 transition-all ${className}`}>
      {/* Toolbar */}
      <div className="flex items-center gap-0.5 px-2 py-1.5 border-b border-outline-variant/10 flex-wrap">
        {/* Bold */}
        <ToolbarBtn
          onClick={() => editor.chain().focus().toggleBold().run()}
          active={editor.isActive("bold")}
          title="Bold (Ctrl+B)"
        >
          <strong>B</strong>
        </ToolbarBtn>

        {/* Italic */}
        <ToolbarBtn
          onClick={() => editor.chain().focus().toggleItalic().run()}
          active={editor.isActive("italic")}
          title="Italic (Ctrl+I)"
        >
          <em>I</em>
        </ToolbarBtn>

        {/* Underline */}
        <ToolbarBtn
          onClick={() => editor.chain().focus().toggleUnderline().run()}
          active={editor.isActive("underline")}
          title="Underline (Ctrl+U)"
        >
          <span className="underline">U</span>
        </ToolbarBtn>

        {/* Strikethrough */}
        <ToolbarBtn
          onClick={() => editor.chain().focus().toggleStrike().run()}
          active={editor.isActive("strike")}
          title="Strikethrough"
        >
          <span className="line-through">S</span>
        </ToolbarBtn>

        {/* Uppercase — one-time transform, preserves bold/italic/underline marks */}
        <ToolbarBtn
          onClick={handleUppercase}
          title="UPPERCASE selected text (select text first • preserves formatting • undo with Ctrl+Z)"
        >
          <span className="text-[11px] font-bold tracking-tight">AA</span>
        </ToolbarBtn>

        <div className="w-px h-5 bg-outline-variant/20 mx-0.5" />

        {/* Bullet List */}
        <ToolbarBtn
          onClick={() => editor.chain().focus().toggleBulletList().run()}
          active={editor.isActive("bulletList")}
          title="Bullet List"
        >
          <span className="material-symbols-outlined text-[16px]">format_list_bulleted</span>
        </ToolbarBtn>

        {/* Numbered List */}
        <ToolbarBtn
          onClick={() => editor.chain().focus().toggleOrderedList().run()}
          active={editor.isActive("orderedList")}
          title="Numbered List"
        >
          <span className="material-symbols-outlined text-[16px]">format_list_numbered</span>
        </ToolbarBtn>

        <div className="w-px h-5 bg-outline-variant/20 mx-0.5" />

        {/* Emoji Picker */}
        <div className="relative" ref={emojiPickerRef}>
          <ToolbarBtn
            onClick={() => setShowEmojiPicker((prev) => !prev)}
            active={showEmojiPicker}
            title="Insert Emoji"
          >
            😀
          </ToolbarBtn>
          {showEmojiPicker && (
            <div className="absolute left-0 top-full mt-1 z-30 bg-surface-container-lowest border border-outline-variant/20 rounded-xl shadow-xl p-2 w-[220px]">
              <p className="text-label-xs text-outline mb-2 px-1">Quick Emoji</p>
              <div className="grid grid-cols-8 gap-0.5">
                {QUICK_EMOJIS.map((emoji) => (
                  <button
                    key={emoji}
                    type="button"
                    onClick={() => insertEmoji(emoji)}
                    className="w-7 h-7 flex items-center justify-center text-[16px] hover:bg-surface-container rounded-lg transition-colors"
                    title={emoji}
                  >
                    {emoji}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Editor Area */}
      <EditorContent editor={editor} />

      {/* Word / char count */}
      <div className="flex items-center justify-end gap-3 px-3 pb-2 text-label-xs text-outline">
        <span>
          {editor.state.doc.textContent.length} chars
        </span>
        <span>
          {editor.state.doc.textContent.split(/\s+/).filter(Boolean).length} words
        </span>
      </div>
    </div>
  );
}

"use client";

/**
 * RichTextPreview.tsx
 * Renders Markdown content as styled HTML with DOMPurify sanitization.
 * Backward compatible with legacy plaintext.
 * 
 * Security: Uses DOMPurify with a strict allowlist to prevent XSS.
 * Parser: Uses `marked` (AST-based) for robust nested formatting support.
 */

import { useMemo, useEffect, useState } from "react";

// ---------------------------------------------------------------------------
// Inline DOMPurify sanitizer (dynamic import to avoid SSR issues)
// ---------------------------------------------------------------------------

function sanitizeHtml(html: string): string {
  // Server-side: return stripped version
  if (typeof window === "undefined") {
    return html
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "")
      .replace(/<[^>]+>/g, "");
  }

  // Client-side: use DOMPurify
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const DOMPurify = require("dompurify");
    return DOMPurify.sanitize(html, {
      ALLOWED_TAGS: [
        "p", "br", "b", "strong", "i", "em", "u", "s", "del",
        "ul", "ol", "li", "span", "div",
      ],
      ALLOWED_ATTR: ["class", "style"],
      FORBID_TAGS: ["script", "iframe", "form", "input", "button", "a", "img"],
      FORBID_ATTR: ["onclick", "onerror", "onload", "href", "src"],
    });
  } catch {
    // Fallback: strip all tags
    return html.replace(/<[^>]+>/g, "");
  }
}

// ---------------------------------------------------------------------------
// Markdown → HTML converter using `marked` (same library as the editor)
// ---------------------------------------------------------------------------

/**
 * Convert Markdown to sanitized HTML for preview.
 *
 * Uses `marked` with gfm=true for ~~strikethrough~~ and nested marks.
 * Underline is stored as raw <u> tag which marked passes through correctly.
 * Legacy plaintext (no markdown markers) is rendered as plain paragraphs.
 *
 * The output of this function is always passed through DOMPurify before
 * being set via dangerouslySetInnerHTML.
 */
function markdownToPreviewHtml(markdown: string): string {
  if (!markdown) return "";
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const { marked } = require("marked") as { marked: typeof import("marked").marked };
  // gfm enables ~~strikethrough~~
  const html = marked.parse(markdown, { gfm: true, breaks: false, async: false }) as string;
  return html.trim();
}

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

interface RichTextPreviewProps {
  content: string;
  platform?: string;
  className?: string;
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function RichTextPreview({
  content,
  className = "",
}: RichTextPreviewProps) {
  const [safeHtml, setSafeHtml] = useState<string>("");

  const rawHtml = useMemo(() => markdownToPreviewHtml(content || ""), [content]);

  useEffect(() => {
    setSafeHtml(sanitizeHtml(rawHtml));
  }, [rawHtml]);

  if (!content) {
    return (
      <p className={`text-outline/40 text-body-sm italic ${className}`}>
        No content to preview...
      </p>
    );
  }

  return (
    <div
      className={`rich-text-preview text-body-sm text-on-surface leading-relaxed ${className}`}
      // Safe: content is DOMPurify-sanitized with strict allowlist
      // eslint-disable-next-line react/no-danger
      dangerouslySetInnerHTML={{ __html: safeHtml }}
    />
  );
}
